    (slot, index) => slot ? `<button class="slot-choice" data-slot="${index}" style="--wc:${weaponColor(slot.id)}" ${slot.id === "sidearm" ? 'disabled aria-label="Sidearm, always kept"' : `aria-label="Swap out ${weaponName(slot.id)}"`}><span class="slot-icon">${weaponIcon(slot.id)}</span><b>${weaponName(slot.id)}</b><i class="slot-ammo${Number.isFinite(slot.ammo) ? "" : " infinite"}"><b style="width:${Math.round(ammoFraction(slot) * 100)}%"></b></i><small>${slot.id === "sidearm" ? "ALWAYS KEPT" : "SWAP OUT"}</small></button>` : ""
